// harpPlot: produce figures from histogram files according to a JSON plot job
// (generated by `harp plot plot_cfg.py`).
#include "Core/interface/Glob.h"
#include "Core/interface/Logger.h"
#include "Core/interface/ParameterSet.h"
#include "Core/interface/PluginLoader.h"
#include "Plot/interface/PlotStyle.h"
#include "Plot/interface/PlotterFactory.h"

#include <TROOT.h>

#include <iostream>

namespace {
void usage() {
  std::cout <<
      "harpPlot - make figures from HARP histogram files\n\n"
      "Usage:\n"
      "  harpPlot <plots.json> [options]\n"
      "  harp plot <plot_cfg.py> [key=value ...]      (python front-end)\n\n"
      "Options:\n"
      "  -o, --output-dir DIR    override outputDir\n"
      "  --only NAME[,NAME]      only draw the plots with these names\n"
      "  --list-plotters         list the available plotter types and exit\n"
      "  -v, --verbose           debug logging\n"
      "  -h, --help              this message\n\n"
      "Example:\n"
      "  harpPlot work/plot_response_cfg.json -o plots/v1\n";
}
}  // namespace

int main(int argc, char** argv) {
  gROOT->SetBatch(true);
  std::string config, outDir, only;
  bool list = false;
  for (int i = 1; i < argc; ++i) {
    std::string a = argv[i];
    auto next = [&](const char* opt) -> std::string { if (i + 1 >= argc) { std::cerr << "missing value for " << opt << "\n"; std::exit(1); } return argv[++i]; };
    if (a == "-h" || a == "--help") { usage(); return 0; }
    else if (a == "-o" || a == "--output-dir") outDir = next("-o");
    else if (a == "--only") only = next("--only");
    else if (a == "--list-plotters") list = true;
    else if (a == "-v" || a == "--verbose") harp::Logger::setLevel(harp::LogLevel::Debug);
    else if (!a.empty() && a[0] == '-') { std::cerr << "unknown option " << a << "\n"; usage(); return 1; }
    else config = a;
  }
  try {
    harp::PluginLoader::loadAll({}, "libHarpPlotters*.so");
    if (list) {
      std::cout << "Available plotters:\n";
      for (const auto& t : harp::PlotterFactory::instance().available()) std::cout << "  " << t << "\n";
      return 0;
    }
    if (config.empty()) { std::cerr << "Error: no plot configuration given. Use -h for help.\n"; return 1; }
    harp::ParameterSet job = harp::ParameterSet::fromFile(config);
    if (!outDir.empty()) job.json()["outputDir"] = outDir;
    harp::PlotStyle::apply();
    harp::PlotContext ctx(job);
    std::vector<std::string> selected = only.empty() ? std::vector<std::string>{} : harp::splitString(only, ',');
    int nDrawn = 0, nFailed = 0;
    for (const auto& ps : job.getVPSet("plots")) {
      const std::string name = ps.get<std::string>("name");
      if (!selected.empty() && std::find(selected.begin(), selected.end(), name) == selected.end()) continue;
      try {
        auto plotter = harp::PlotterFactory::instance().create(ps.get<std::string>("@type"), ps, ctx);
        plotter->draw();
        ++nDrawn;
      } catch (const std::exception& e) {
        ++nFailed;
        HARP_ERROR("harpPlot") << "plot '" << name << "' failed: " << e.what();
      }
    }
    HARP_INFO("harpPlot") << nDrawn << " plot(s) drawn, " << nFailed << " failed, output in " << ctx.outputDir();
    return nFailed == 0 ? 0 : 2;
  } catch (const std::exception& e) {
    std::cerr << "\n[FATAL] " << e.what() << "\n";
    return 1;
  }
}
